-- Novro migration 0024: remove numeric suffixes generated by the old provider
-- linking fallback while preserving administrator-defined public aliases.

CREATE TEMPORARY TABLE novro_generated_route_targets (
    route_id CHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL PRIMARY KEY,
    target_public_name VARCHAR(256) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO novro_generated_route_targets (route_id, target_public_name)
SELECT
    route.id,
    CASE
        WHEN LEFT(
                LOWER(route.public_name),
                CHAR_LENGTH(CONCAT(configured_provider.code, '-', catalog_model.upstream_name, '-'))
            ) = LOWER(CONCAT(configured_provider.code, '-', catalog_model.upstream_name, '-'))
         AND SUBSTRING(
                route.public_name,
                CHAR_LENGTH(CONCAT(configured_provider.code, '-', catalog_model.upstream_name, '-')) + 1
            ) REGEXP '^[0-9]+$'
            THEN catalog_model.upstream_name
        ELSE route.public_name
    END
FROM model_routes AS route
JOIN providers AS configured_provider ON configured_provider.id = route.provider_id
JOIN upstream_models AS catalog_model ON catalog_model.id = route.upstream_model_id;

CREATE TEMPORARY TABLE novro_generated_route_map (
    route_id CHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL PRIMARY KEY,
    canonical_route_id CHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    KEY novro_generated_route_map_canonical_id (canonical_route_id)
) ENGINE=InnoDB;

INSERT INTO novro_generated_route_map (route_id, canonical_route_id)
SELECT ranked.route_id, ranked.canonical_route_id
FROM (
    SELECT
        route.id AS route_id,
        FIRST_VALUE(route.id) OVER (
            PARTITION BY targets.target_public_name, route.provider_id, route.upstream_model_id
            ORDER BY
                (route.deleted_at IS NULL) DESC,
                (route.status = 'active') DESC,
                route.created_at ASC,
                route.id ASC
        ) AS canonical_route_id
    FROM model_routes AS route
    JOIN novro_generated_route_targets AS targets ON targets.route_id = route.id
) AS ranked;

UPDATE api_usages AS usage_record
JOIN novro_generated_route_map AS route_map ON route_map.route_id = usage_record.model_route_id
SET usage_record.model_route_id = route_map.canonical_route_id
WHERE route_map.route_id <> route_map.canonical_route_id;

DELETE duplicate_route
FROM model_routes AS duplicate_route
JOIN novro_generated_route_map AS route_map ON route_map.route_id = duplicate_route.id
WHERE route_map.route_id <> route_map.canonical_route_id;

UPDATE model_routes AS route
JOIN novro_generated_route_targets AS targets ON targets.route_id = route.id
JOIN novro_generated_route_map AS route_map
  ON route_map.route_id = route.id
 AND route_map.canonical_route_id = route.id
SET route.public_name = targets.target_public_name;

DROP TEMPORARY TABLE novro_generated_route_map;
DROP TEMPORARY TABLE novro_generated_route_targets;
